.flame{position:absolute;pointer-events:none;z-index:4997;transform-origin:var(--ox,0) var(--oy,50%)}
.flame b{position:absolute;inset:0;transform-origin:var(--ox,0) var(--oy,50%);background-repeat:no-repeat;background-size:600% 100%;animation:flame .9s ease-out forwards,flick .3s steps(6) infinite}
.flame.blast b{background-image:url('myth/flame_blast.png')}
.flame.spray b{background-image:url('myth/flame_arc.png');animation:flameArc .9s ease-out forwards,flick .3s steps(6) infinite}
@keyframes flameArc{0%{transform:scale(.2);opacity:0}15%{transform:scale(1);opacity:1}70%{opacity:.95}100%{transform:scale(1.04);opacity:0}}
@keyframes flick{from{background-position:0 0}to{background-position:120% 0}}   /* 6 frames */
/* the Dragon blowing fire as it soars over on its fire run (inside its picture, so it follows its mouth) */
