const fl=document.createElement('div'), b=document.createElement('b'); fl.appendChild(b);
const ty=t.y-(t.T.flying?t.alt:0);
if(!t.T.flying&&Math.abs(t.x-mx)<9&&ty>my){   // close in front, on the ground: it sprays fire down at them (the curved flame)
  const P=FLAME.arc, hh=Math.max(4,ty-my+1), ww=hh*P.ar;
  fl.className='flame spray'; fl.style.width=ww+'%'; fl.style.height=(hh/AH*100)+'%';
  fl.style.left=(mx-P.tip[0]*ww)+'%'; fl.style.top=((my-P.tip[1]*hh)/AH*100)+'%';
  fl.style.setProperty('--ox',(P.tip[0]*100)+'%'); fl.style.setProperty('--oy',(P.tip[1]*100)+'%');
  fl.style.transform='scaleX('+(t.x>=mx?1:-1)+')';
} else {                                        // farther off: a straight blast of fire out to them
  const P=FLAME.blast, hh=Math.max(3,Math.min(9,dl*0.6));
  fl.className='flame blast'; fl.style.width=dl+'%'; fl.style.height=(hh/AH*100)+'%';
  fl.style.left=(mx-P.tip[0]*dl)+'%'; fl.style.top=((my-P.tip[1]*hh)/AH*100)+'%';
  fl.style.setProperty('--ox',(P.tip[0]*100)+'%'); fl.style.setProperty('--oy',(P.tip[1]*100)+'%');
  fl.style.transform='rotate('+(ang*180/Math.PI).toFixed(1)+'deg)'+(Math.cos(ang)<0?' scaleY(-1)':'');   // (kept right way up when it breathes to the left)
}
b.addEventListener('animationend',e=>{ if(e.animationName!=='flick') fl.remove(); }); arena.appendChild(fl);
